class Solution {
public:
    int tripletCount(vector<int>& a, vector<int>& b, vector<int>& c) {
        auto get_counts = [](const vector<int>& arr) {
            int even = 0;
            for (int x : arr) {
                if (__builtin_parity(x) == 0) even++;
            }
            return make_pair(even, (int)arr.size() - even);
        };
        auto [ea, oa] = get_counts(a);
        auto [eb, ob] = get_counts(b);
        auto [ec, oc] = get_counts(c);
        return (ea * eb * ec) + (ea * ob * oc) + (oa * eb * oc) + (oa * ob * ec);
    }
};

class Solution {
    private int[] getCounts(int[] arr) {
        int even = 0;
        for (int x : arr) {
            if (Integer.bitCount(x) % 2 == 0) even++;
        }
        return new int[]{even, arr.length - even};
    }
    public int tripletCount(int[] a, int[] b, int[] c) {
        int[] ca = getCounts(a);
        int[] cb = getCounts(b);
        int[] cc = getCounts(c);
        int ea = ca[0], oa = ca[1];
        int eb = cb[0], ob = cb[1];
        int ec = cc[0], oc = cc[1];
        return (ea * eb * ec) + (ea * ob * oc) + (oa * eb * oc) + (oa * ob * ec);
    }
}

var tripletCount = function(a, b, c) {
    function getCounts(arr) {
        let even = 0;
        for (let x of arr) {
            let bits = 0;
            while (x > 0) {
                bits += (x & 1);
                x >>= 1;
            }
            if (bits % 2 === 0) even++;
        }
        return [even, arr.length - even];
    }
    const [ea, oa] = getCounts(a);
    const [eb, ob] = getCounts(b);
    const [ec, oc] = getCounts(c);
    return (ea * eb * ec) + (ea * ob * oc) + (oa * eb * oc) + (oa * ob * ec);
};
